// 1. Получаем все входящие элементы (используем $input.all() вместо items)
const items = $input.all();

// 2. Пытаемся безопасно достать "Главный ключ" из контекста один раз
let mainKey = "статьи";
try {
  // Используем .first().json и опциональную цепочку ?.
  const context = $('When Executed by Another Workflow').first().json;
  mainKey = context?.контекст?.задача?.['Главный ключ'] || "статьи";
} catch (e) {
  // Если узел недоступен, останется дефолтное "статьи"
  console.log("Контекст недоступен:", e.message);
}

// 3. Обрабатываем каждый элемент
return items.map(item => {
  const raw = String(item.json?.output || '').trim();

  // Пытаемся найти JSON регуляркой
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  let parsed = null;

  if (jsonMatch) {
    try {
      // Очищаем от невидимых символов управления и парсим
      const cleanCandidate = jsonMatch[0].replace(/[\u0000-\u001F\u007F-\u009F]/g, "");
      parsed = JSON.parse(cleanCandidate);
    } catch (e) {
      parsed = null;
    }
  }

  // ✅ ВАРИАНТ А: Если парсинг прошел успешно
  if (parsed && typeof parsed === 'object') {
    return {
      json: {
        technical_prompt: parsed.technical_prompt || "Error: prompt missing",
        alt_text: parsed.alt_text || `Изображение для ${mainKey}` 
      }
    };
  }

  // ✅ ВАРИАНТ Б: Если это просто текст (не JSON)
  // Берем первые 500 символов как промпт
  return {
    json: {
      technical_prompt: raw.slice(0, 500) || "Error: empty input", 
      alt_text: "Изображение для " + mainKey
    }
  };
});

/**
 * СБОРКА УНИФИЦИРОВАННОГО ХУКА (КИРПИЧ №1) — V.3.5 (REPAIR MODE)
 */

// 1. ПОЛУЧАЕМ ДАННЫЕ
const journalistNode = $('Агент Журналист').first();
let rawJournalist = String(journalistNode?.json?.output || '');

// 2. ФУНКЦИЯ "ЛЕЧЕНИЯ" ОБРЕЗАННОГО JSON
function repairJson(jsonStr) {
    let cleaned = jsonStr.replace(/```json\s*|```/gi, '').trim();

    // Если JSON не закрыт (бывает при лимите токенов)
    let openBraces = (cleaned.match(/\{/g) || []).length;
    let closeBraces = (cleaned.match(/\}/g) || []).length;
    let quotes = (cleaned.match(/"/g) || []).length;

    // Если кавычек нечетное количество — закрываем последнюю строку
    if (quotes % 2 !== 0) {
        cleaned += '"';
    }
    // Если скобок не хватает — закрываем объект
    if (openBraces > closeBraces) {
        for (let i = 0; i < (openBraces - closeBraces); i++) {
            cleaned += '}';
        }
    }
    return cleaned;
}

// 3. ОЧИСТКА И ПАРСИНГ
let cleaned = repairJson(rawJournalist);
cleaned = cleaned.replace(/[\u0000-\u001F\u007F-\u009F]/g, ""); // Убираем битые символы

let journalist;
try {
    journalist = JSON.parse(cleaned);
} catch (e) {
    // Если даже "лечилка" не помогла, создаем объект-заглушку из того, что удалось спасти
    console.error("Critical JSON error, using fallback logic");
    journalist = {
        h1: (rawJournalist.match(/"h1":\s*"([^"]+)"/) || [null, "Ошибка генерации"])[1],
        slug: (rawJournalist.match(/"slug":\s*"([^"]+)"/) || [null, "error-slug"])[1],
        intro_html: "⚠️ Внимание: Контент был обрезан нейросетью из-за лимита токенов."
    };
}

const imageGen = $('Генерация изображения').first()?.json || {};
const trigger = $('When Executed by Another Workflow').first()?.json || {};

// 4. ФОРМИРУЕМ ВЫХОД
const summary = journalist.summary_html || "";
const intro = journalist.intro_html || "";

return {
  json: {
    id: 1,                 
    type: "HOOK",          
    h1: journalist.h1 || "Без заголовка",     
    slug: journalist.slug || "",
    meta_description: journalist.meta_description || "",
    result: (summary + "\n\n" + intro).trim(), 

    featured_image: {
        url: imageGen.mediaUrl || "",
        alt: imageGen.altText || "",
        mediaId: imageGen.mediaId || 0
    },

    metadata: {
        brand: trigger.контекст?.настройки?.brand_name || "Firsanov",
        publish_date: new Date().toISOString()
    }
  }
};
